import copy
import itertools
import unittest
from decimal import Decimal
from fractions import Fraction

from intervals import merge_intervals


class MergeIntervalsTests(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(merge_intervals([]), [])

    def test_sorted_disjoint_output(self):
        self.assertEqual(merge_intervals([[7, 9], [1, 2], [4, 5]]), [[1, 2], [4, 5], [7, 9]])

    def test_overlapping_and_touching(self):
        self.assertEqual(merge_intervals([[5, 8], [1, 3], [3, 6]]), [[1, 8]])

    def test_nested_duplicates_and_zero_width(self):
        self.assertEqual(merge_intervals([[1, 8], [2, 3], [1, 8], [8, 8], [10, 10]]), [[1, 8], [10, 10]])

    def test_negative_and_fractional_endpoints(self):
        self.assertEqual(merge_intervals([[-1.5, 0.25], [-3, -1.5], [2.5, 4]]), [[-3, 0.25], [2.5, 4]])

    def test_decimal_and_fraction_endpoints(self):
        for number_type in (Decimal, Fraction):
            with self.subTest(number_type=number_type):
                self.assertEqual(merge_intervals([(number_type(1), number_type(2)), (number_type(2), number_type(3))]), [[number_type(1), number_type(3)]])

    def test_reversed_endpoints_are_rejected(self):
        for items in ([[2, 1]], [[0, 10], [5, 3]], [[5, 3], [0, 10]]):
            original = copy.deepcopy(items)
            with self.subTest(items=items):
                with self.assertRaises(ValueError):
                    merge_intervals(items)
                self.assertEqual(items, original)

    def test_does_not_mutate_or_alias_input_pairs(self):
        items = [[5, 6], [1, 3], [2, 4]]
        original = copy.deepcopy(items)
        result = merge_intervals(items)
        self.assertEqual(items, original)
        self.assertEqual(result, [[1, 4], [5, 6]])
        result[0][0] = -100
        result[1][1] = 100
        self.assertEqual(items, original)

    def test_all_input_orders_and_iterators(self):
        items = [(1, 2), (2, 5), (3, 4), (7, 8)]
        for order in itertools.permutations(items):
            with self.subTest(order=order):
                self.assertEqual(merge_intervals(iter(order)), [[1, 5], [7, 8]])


if __name__ == "__main__":
    unittest.main()
